package httpserver

import (
	"io"
	"net/http"
)

const demoWorkbenchCSS = `
:root{color-scheme:light;font-family:Inter,"PingFang SC","Microsoft YaHei",ui-sans-serif,system-ui,-apple-system,sans-serif;color:#172033;background:#f4f6f8;line-height:1.55;--ink:#172033;--muted:#657084;--line:#dce1e8;--surface:#fff;--soft:#eef3f8;--accent:#2457a7;--accent-dark:#173f7c;--danger:#a33838;--success:#1f6b4f}
*{box-sizing:border-box}body{margin:0;min-height:100vh;background:linear-gradient(180deg,#eef2f6 0,#f7f8fa 230px);font-size:14px}a{color:var(--accent);text-underline-offset:3px}a:hover{color:var(--accent-dark)}body>header,body>main{width:min(1280px,calc(100% - 40px));margin-inline:auto}body>header{margin-top:24px;padding:20px 24px;background:rgba(255,255,255,.92);border:1px solid var(--line);border-radius:10px 10px 0 0;box-shadow:0 8px 28px rgba(29,42,61,.06)}body>main{margin-top:24px;margin-bottom:64px}body>header+main{margin-top:0;padding:24px;background:var(--surface);border:1px solid var(--line);border-top:0;border-radius:0 0 10px 10px}h1,h2,h3{line-height:1.25;color:var(--ink)}h1{margin:.25rem 0 .75rem;font-size:clamp(26px,4vw,38px);letter-spacing:-.025em}h2{font-size:19px;margin:0 0 16px}h3{font-size:15px;margin:0 0 8px}p{max-width:78ch}nav{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin:14px 0}nav a{display:inline-flex;align-items:center;min-height:36px;padding:7px 11px;border:1px solid var(--line);border-radius:6px;background:#fff;text-decoration:none;font-weight:600}nav a:hover{background:var(--soft);border-color:#b8c7dc}section{margin:18px 0;padding:22px;background:var(--surface);border:1px solid var(--line);border-radius:8px;box-shadow:0 4px 16px rgba(29,42,61,.035);overflow-x:auto}section>p:first-of-type{color:var(--muted)}form{display:grid;grid-template-columns:repeat(auto-fit,minmax(210px,1fr));gap:14px 16px;align-items:end;margin:16px 0}form>p,form>fieldset,form>table,form>[role="alert"],form>[role="status"]{grid-column:1/-1}label{display:grid;gap:6px;color:#3d485b;font-size:13px;font-weight:650}input,select,textarea{width:100%;min-height:40px;padding:9px 11px;border:1px solid #bcc5d1;border-radius:6px;background:#fff;color:var(--ink);font:inherit;transition:border-color .15s,box-shadow .15s}textarea{min-height:92px;resize:vertical}input:focus,select:focus,textarea:focus{outline:0;border-color:var(--accent);box-shadow:0 0 0 3px rgba(36,87,167,.13)}button,.button{display:inline-flex;align-items:center;justify-content:center;min-height:40px;padding:9px 15px;border:1px solid var(--accent);border-radius:6px;background:var(--accent);color:#fff;font:inherit;font-weight:700;text-decoration:none;cursor:pointer}button:hover,.button:hover{background:var(--accent-dark);border-color:var(--accent-dark);color:#fff}button:disabled{opacity:.55;cursor:not-allowed}table{width:100%;min-width:760px;border-collapse:collapse;background:#fff}th,td{padding:12px 13px;border-bottom:1px solid #e5e9ee;text-align:left;vertical-align:top}th{background:#f2f5f8;color:#455166;font-size:12px;text-transform:none;letter-spacing:.02em}tbody tr:hover{background:#f8fafc}[role="alert"]{padding:11px 13px;border-left:4px solid var(--danger);background:#fff0f0;color:#7d2929;border-radius:4px}[role="status"]{padding:11px 13px;border-left:4px solid var(--success);background:#edf8f3;color:#195b43;border-radius:4px}code{padding:2px 5px;border-radius:4px;background:#edf1f5;font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:.9em}.app-header{display:flex;justify-content:space-between;gap:20px;align-items:center}.brand{display:flex;gap:12px;align-items:center;font-weight:800}.brand-mark{display:grid;width:38px;height:38px;place-items:center;border-radius:8px;background:#1d3150;color:#fff}.user-chip{color:var(--muted);font-size:13px}.hero{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:28px;align-items:end;padding:30px;background:var(--surface);border:1px solid var(--line);border-radius:10px}.eyebrow{margin:0;color:var(--accent);font-size:12px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.hero-copy{max-width:720px;color:var(--muted);font-size:15px}.status-chip{display:inline-flex;padding:6px 10px;border:1px solid #b9ddcf;border-radius:999px;background:#edf8f3;color:#195b43;font-size:12px;font-weight:750}.guide{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:16px 0 22px}.guide-step{padding:16px;background:#f8fafc;border:1px solid var(--line);border-radius:8px}.guide-step span{display:grid;width:26px;height:26px;place-items:center;margin-bottom:10px;border-radius:50%;background:#dfe9f7;color:var(--accent);font-weight:800}.guide-step p{margin:0;color:var(--muted);font-size:13px}.module-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.module-card{display:block;min-height:142px;padding:18px;border:1px solid var(--line);border-radius:8px;background:#fff;text-decoration:none;transition:transform .14s,border-color .14s,box-shadow .14s}.module-card:hover{transform:translateY(-2px);border-color:#a7b9d2;box-shadow:0 10px 24px rgba(30,49,78,.08)}.module-card strong{display:block;margin-bottom:6px;color:var(--ink);font-size:16px}.module-card small{color:var(--muted);font-size:13px}.module-card .action{display:block;margin-top:16px;color:var(--accent);font-weight:750}.page-note{padding:14px 16px;border:1px solid #d6dfeb;border-radius:7px;background:#f5f8fc;color:#4c5b70}.quiet-actions{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-top:20px}.quiet-actions form{display:block;margin:0}.quiet-actions button{background:#fff;border-color:#c8d0dc;color:#435065}.quiet-actions button:hover{background:#f1f4f8;color:#172033}
nav a[aria-current="page"]{background:var(--accent);border-color:var(--accent);color:#fff;box-shadow:inset 0 -2px 0 rgba(0,0,0,.16)}nav a[aria-current="page"]:hover{background:var(--accent-dark);border-color:var(--accent-dark);color:#fff}
@media(max-width:760px){body>header,body>main{width:min(100% - 20px,1280px)}body>header,body>header+main{padding:17px}.app-header,.hero{grid-template-columns:1fr;display:grid}.guide{grid-template-columns:1fr}.hero{padding:22px}section{padding:17px}form{grid-template-columns:1fr}table{font-size:13px}}
`

func demoWorkbenchStyle(w http.ResponseWriter, _ *http.Request) {
	w.Header().Set("Content-Type", "text/css; charset=utf-8")
	w.Header().Set("Cache-Control", "public, max-age=300")
	_, _ = io.WriteString(w, demoWorkbenchCSS)
}
